from pathlib import Path
import json,csv,hashlib,datetime
p=Path.home()/'aipharma_analogues_20261016';o=p/'safety_audit';h=Path.home()/'aipharma_holdout_20261016'
parents=json.loads((p/'parents.json').read_text());pr={r['parent_id']:r for r in json.loads((p/'parent_measurement_provenance.json').read_text())};pred={r['parent_id']:r for r in json.loads((p/'all_screened.json').read_text()) if r.get('is_parent')};assays={r['assay_chembl_id']:r for r in json.loads((h/'raw/boundary_assays_all.json').read_text())['assays']}
sources=[{'id':'gal_gem','url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6251034/','type':'human randomized combination study','finding':'No apparent liver toxicity difference reported between galunisertib+gemcitabine and placebo+gemcitabine. This is not a DILI-negative adjudication.'},{'id':'gal_durva','url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC7944986/','type':'human combination study','finding':'ALT and AST treatment-related elevations reported; coadministration of durvalumab prevents single-drug attribution.'},{'id':'aza','url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6231184/','type':'primary preclinical discovery study','finding':'Selected compounds profiled for CYP inhibition/microsomal stability; efficacy study reports no significant weight loss. No compound-specific clinical DILI-negative label established for CHEMBL4280731.'},{'id':'ly','url':'https://www.sciencedirect.com/science/article/abs/pii/S0041008X18303120','type':'primary in vitro/ex vivo study abstract','finding':'LY2109761 evaluated for antifibrotic effects in cell lines and liver slices; antifibrotic activity does not establish clinical liver safety.'},{'id':'bms','url':'https://pubmed.ncbi.nlm.nih.gov/32071685/','type':'primary preclinical study abstract','finding':'Cardiovascular toxicology addressed for BMS-986260. Evidence is not transferable as a liver-safety label to other compounds from same paper.'},{'id':'tdc','url':'https://tdcommons.ai/single_pred_tasks/tox/#dili-drug-induced-liver-injury','type':'dataset documentation','finding':'DILI: 475 compounds, binary classification; class1 liver injury, class0 not. Score is not dose-specific clinical event probability.'},{'id':'model','url':'https://github.com/swansonk14/admet_ai','type':'model developer documentation','finding':'ADMET-AI uses models trained on TDC data. Local metadata identifies human DILI classification, 475 entries; not molecule-level experimental labels.'},{'id':'ly_identity','url':'https://www.guidetopharmacology.org/GRAC/LigandDisplayForward?ligandId=8075','type':'curated identity source','finding':'CHEMBL260015 maps to LY2109761.'}]
rows=[]
for r in parents:
 pid=r['parent_id'];a=assays[pr[pid]['assay_id']];mol=json.loads((o/f'{pid}.json').read_text());desc=a.get('description','');cell=any(k in desc.lower() for k in ['in human t cells','in human primary t-cells','in human a549 cells','human nhlf cells'])
 status='No adequate compound-specific liver-safety ground truth located in this targeted review';ev=[]
 if pid=='CHEMBL2364611':status='Human combination data: mixed liver-related findings; not a validated positive/negative DILI label';ev=['gal_gem','gal_durva']
 if pid=='CHEMBL260015':status='Preclinical liver-related pharmacology located; not clinical DILI ground truth';ev=['ly','ly_identity']
 if pid=='CHEMBL4280731':status='Source-paper ADME/efficacy context located; no adjudicated DILI label established';ev=['aza']
 if pid in ['CHEMBL4458215','CHEMBL4440988']:ev=['bms']
 name=mol.get('pref_name') or ('LY2109761' if pid=='CHEMBL260015' else 'unnamed research compound')
 docs=[]
 for d in r['documents']:
  fn=o/f'{d}.json'
  if fn.exists():
   dd=json.loads(fn.read_text());docs.append({'document_id':d,'doi':dd.get('doi'),'pubmed_id':dd.get('pubmed_id'),'title':dd.get('title')})
 rows.append({'parent_id':pid,'name':name,'DILI_prediction':pred[pid]['toxicity']['DILI'],'evidence_status':status,'DILI_ground_truth_label':None,'source_ids':ev,'representative_assay_description':desc,'explicit_cellular_assay_description':cell,'representative_IC50_nM':pr[pid]['representative_IC50_nM'],'pooled_median_pchembl':r['median_pchembl'],'sources_from_chembl':docs})
assert len(rows)==12 and all(x['DILI_ground_truth_label'] is None for x in rows)
summary={'date_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'references':12,'usable_adjudicated_DILI_labels':0,'DILI_score_range':[min(x['DILI_prediction'] for x in rows),max(x['DILI_prediction'] for x in rows)],'explicit_cellular_representative_assays':sum(x['explicit_cellular_assay_description'] for x in rows),'conclusion':'Neither model accuracy nor false-positive rate can be estimated from these references. Do not treat all69 rejected analogues as experimentally toxic; do not relax thresholds to manufacture passing compounds.','important_correction':'assay_type B plus confidence9 did not ensure a biochemical-only endpoint. Several explicit cell-signaling IC50 assays were included. Earlier biochemical-only descriptions are too strong; prior results are exploratory mixed-endpoint analyses pending assay-level review.','search_limits':'Targeted identity, original-publication and clinical study search; not systematic review. Some publisher/NCBI pages inaccessible; abstract-only evidence not treated as full text. Same-paper lead safety findings not transferred to other structures. Training overlap and calibration not established.'}
(o/'evidence_matrix.json').write_text(json.dumps({'summary':summary,'sources':sources,'references':rows},indent=2))
with (o/'evidence_matrix.csv').open('w',newline='') as f:
 fields=['parent_id','name','DILI_prediction','evidence_status','DILI_ground_truth_label','explicit_cellular_assay_description'];w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(rows)
lines=['# ALK5 referansları: DILI güvenlilik denetimi — 2026-10-16','','## Karar','','**DILI modelinin bu 12 referansta doğru veya yanlış olduğunu gösterecek yeterli deneysel etiket elde edilemedi.** Dolayısıyla modelin doğruluğu, yanlış pozitif oranı veya 0.5 eşiğinin uygunluğu hesaplanmadı. 69 analogun elenmesi gerçek toksisite kanıtı değildir.','', '12 referansın DILI model skorları 0.841–0.999 aralığında. Yüksek skorlar hasta düzeyinde %84–100 karaciğer hasarı olasılığı anlamına gelmez. Model çıktısı insan DILI sınıflandırma skorudur; doz, uygulama süresi ve kombinasyon koşulları bu girdide bulunmaz. [TDC tanımı](https://tdcommons.ai/single_pred_tasks/tox/#dili-drug-induced-liver-injury).','', '## Bulunan kanıt','','Galunisertib (CHEMBL2364611): gemcitabinle randomize kombinasyon çalışmasında gruplar arasında belirgin ek karaciğer toksisitesi farkı bildirilmedi. Durvalumab kombinasyonunda ise karaciğer enzim artışları raporlandı. Kombinasyonlar ve hasta koşulları nedeniyle bu veriler galunisertibe tek başına kesin DILI-pozitif veya DILI-negatif etiket atamaz. [Karşılaştırmalı çalışma](https://pmc.ncbi.nlm.nih.gov/articles/PMC6251034/), [durvalumab çalışması](https://pmc.ncbi.nlm.nih.gov/articles/PMC7944986/).','', 'LY2109761 (CHEMBL260015): hücre ve karaciğer kesiti modellerinde antifibrotik araştırma bulundu. Bu, insan karaciğer güvenliliği kanıtı değildir. [Birincil çalışma özeti](https://www.sciencedirect.com/science/article/abs/pii/S0041008X18303120), [kimlik eşlemesi](https://www.guidetopharmacology.org/GRAC/LigandDisplayForward?ligandId=8075).','', 'CHEMBL4280731 kaynak yayını: bazı bileşiklerde metabolik kararlılık/CYP profili ve fare etkinliği incelenmiş. Metabolik kararlılık, CYP inhibisyonu veya kilo kaybı gözlenmemesi, klinik DILI-negatif etiket değildir. Yazıdaki belirli bileşiğin verisi yapı eşlemesi tamamlanmadan bu referansa aktarılmadı. [Birincil çalışma](https://pmc.ncbi.nlm.nih.gov/articles/PMC6231184/).','', 'CHEMBL4458215 ve CHEMBL4440988 aynı BMS-986260 keşif yayınından geliyor. Yayındaki başka bir lider molekülün kardiyovasküler toksikoloji sonucu bu yapılara ve karaciğer güvenliliğine aktarılmadı. [Kaynak yayın özeti](https://pubmed.ncbi.nlm.nih.gov/32071685/).','', 'Diğer referanslarda hedefe etki kayıtları doğrulandı; bu taramada moleküle özgü, karşılaştırılabilir ve güvenilir insan DILI etiketi bulunamadı. Bu ifade veri yokluğunu güvenlilik olarak sınıflandırmaz.','', '## Referans bazında durum','','| ChEMBL | Kimlik | DILI skoru | Güvenilir DILI etiketi |','|---|---|---:|---|']
for r in rows:lines.append(f"| {r['parent_id']} | {r['name']} | {r['DILI_prediction']:.3f} | Bilinmiyor |")
lines+=['','## Ek yöntem düzeltmesi','','Referansların assay açıklamalarında 4 açık hücresel sinyal ölçümü saptandı. ChEMBL B assay türü ve hedef eşleştirme güveni 9 olması tek başına saf biyokimyasal ölçüm garantisi değil. Bazı proteinlerin Sf9 hücrelerinde üretilmiş olması ise kendi başına hücresel assay anlamına gelmez; deney açıklamasının tamamı okunmalıdır.','', 'Bu nedenle önceki raporlardaki “yalnızca biyokimyasal” tanımı düzeltilmelidir. Kaydedilen sayısal sonuçlar değişmedi; ancak biyokimyasal bağlanmaya özgü doğrulama gibi sunulmamalı. Enzim/kinaz ölçümü, hücresel SMAD yanıtı, mutant ve yabanıl tip ayrımlarıyla yeni veri denetimi gerekir. Eski açılmış test yeniden kör test sayılmaz.','', '## Sonraki adım','','1. Aktivite veri setini assay açıklaması ve ölçüm formatına göre yeniden ayırmak; belirsiz formatları ayrı tutmak.','2. DILI filtresini bağımsız, etiketli ve eğitim örtüşmesi denetlenmiş güvenlilik verisinde değerlendirmek. Bu 12 referans o doğrulamayı sağlamıyor.','3. Kanıt oluşana kadar ADMET skorlarını belirsiz risk işareti olarak sunmak; geçmiş 0.5 kapısıyla elde edilen sıfır seçimi değiştirmeden arşivlemek.','', 'Bu denetim sistematik literatür taraması değildir. Bazı tam metinlere erişilemedi; özetler tam metin yerine sayılmadı. Sentez, global yenilik ve 69 analogun deneysel güvenliliği bu çalışmada doğrulanmadı.','', '## Dosyalar','','- evidence_matrix.json / .csv: 12 referans, kaynak bağlantıları, bilinmeyen etiketler ve assay açıklamaları.','- identity_summary.json ve CHEMBL*.json: resmi kimlik ve yayın kayıtları.','- build_alk5_safety_audit.py / fetch_alk5_safety_sources.py: kodlar.']
(o/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,indent=2))
